<?php
require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','accountant']);$bid=current_branch_id();
$export=$_GET['export']??'';if($export){$allowed=['members','payments','expenses','attendance'];if(!in_array($export,$allowed,true))$export='';}
if($export){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="fitcore_'.$export.'_'.date('Ymd').'.csv"');$out=fopen('php://output','w');
 if($export==='members'){fputcsv($out,['Member ID','Name','Phone','Plan','Start','End','Status']);foreach(query_all("SELECT m.member_code,CONCAT(m.first_name,' ',m.last_name) name,m.phone,p.name plan,m.membership_start,m.membership_end,m.status FROM members m LEFT JOIN membership_plans p ON p.id=m.membership_plan_id WHERE m.branch_id=?",[$bid]) as $r)fputcsv($out,$r);}
 if($export==='payments'){fputcsv($out,['Reference','Member','Type','Method','Date','Amount','Status']);foreach(query_all("SELECT p.reference_no,CONCAT(m.first_name,' ',m.last_name) member,p.payment_type,p.method,p.payment_date,p.amount,p.status FROM payments p JOIN members m ON m.id=p.member_id WHERE p.branch_id=? ORDER BY p.payment_date DESC",[$bid]) as $r)fputcsv($out,$r);}
 if($export==='expenses'){fputcsv($out,['Date','Category','Title','Vendor','Method','Amount']);foreach(query_all("SELECT expense_date,category,title,vendor,payment_method,amount FROM expenses WHERE branch_id=? ORDER BY expense_date DESC",[$bid]) as $r)fputcsv($out,$r);}
 if($export==='attendance'){fputcsv($out,['Member ID','Member','Check In','Check Out','Method']);foreach(query_all("SELECT m.member_code,CONCAT(m.first_name,' ',m.last_name) member,a.check_in,a.check_out,a.method FROM attendance a JOIN members m ON m.id=a.member_id WHERE a.branch_id=? ORDER BY a.check_in DESC",[$bid]) as $r)fputcsv($out,$r);}
 fclose($out);exit;}
$summary=['Members'=>(int)query_value('SELECT COUNT(*) FROM members WHERE branch_id=?',[$bid]),'Active'=>(int)query_value("SELECT COUNT(*) FROM members WHERE branch_id=? AND status='active' AND membership_end>=CURDATE()",[$bid]),'Month Revenue'=>(float)query_value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE branch_id=? AND status='paid' AND payment_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]),'Month Expenses'=>(float)query_value("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE branch_id=? AND expense_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]),'Month Visits'=>(int)query_value("SELECT COUNT(*) FROM attendance WHERE branch_id=? AND check_in>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid])];
$pageTitle='Reports & Export';include __DIR__.'/../includes/header.php'; ?>
<div class="hero-card" style="min-height:200px"><div class="hero-copy"><span class="hero-kicker"><i class="fa-solid fa-file-export"></i> Management reporting</span><h2>Clean operational data, ready to export.</h2><p>Download CSV reports for management review, accounting work, analysis or backup. Browser print can also save this summary as PDF.</p><button onclick="window.print()" class="btn btn-primary mt-2"><i class="fa-solid fa-print me-2"></i>Print / Save PDF</button></div></div>
<div class="metric-strip mt-3"><?php foreach($summary as $k=>$v): ?><div class="metric-box"><small><?= e($k) ?></small><strong><?= str_contains($k,'Revenue')||str_contains($k,'Expenses')?money($v):number_format($v) ?></strong></div><?php endforeach; ?></div>
<div class="grid-2"><div class="panel"><div class="panel-head"><div><h3>Member master report</h3><p>Member ID, membership period, plan and status</p></div></div><a class="btn btn-primary" href="?export=members"><i class="fa-solid fa-download me-2"></i>Download members CSV</a></div><div class="panel"><div class="panel-head"><div><h3>Payment ledger</h3><p>References, payment type, method and amount</p></div></div><a class="btn btn-primary" href="?export=payments"><i class="fa-solid fa-download me-2"></i>Download payments CSV</a></div><div class="panel"><div class="panel-head"><div><h3>Expense ledger</h3><p>Category, vendor and recorded costs</p></div></div><a class="btn btn-primary" href="?export=expenses"><i class="fa-solid fa-download me-2"></i>Download expenses CSV</a></div><div class="panel"><div class="panel-head"><div><h3>Attendance log</h3><p>Member check-in/check-out activity</p></div></div><a class="btn btn-primary" href="?export=attendance"><i class="fa-solid fa-download me-2"></i>Download attendance CSV</a></div></div>
